#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long maxScore(std::vector<int>& nums1, std::vector<int>& nums2, int k) {
        int n1 = nums1.size(), n2 = nums2.size();
        std::vector<std::vector<long long>> prev(k + 1, std::vector<long long>(n2 + 1, -1e18));
        for (int j = 0; j <= n2; ++j) prev[0][j] = 0;
        for (int i = 1; i <= n1; ++i) {
            auto cur = prev;
            long long v1 = nums1[i - 1];
            for (int p = 1; p <= std::min(k, i); ++p) {
                for (int j = p; j <= n2; ++j) {
                    long long v2 = nums2[j - 1];
                    if (prev[p - 1][j - 1] > -1e17) {
                        cur[p][j] = std::max(cur[p][j], prev[p - 1][j - 1] + v1 * v2);
                    }
                    cur[p][j] = std::max(cur[p][j], cur[p][j - 1]);
                }
            }
            prev = cur;
        }
        return prev[k][n2];
    }
};

import java.util.*;

class Solution {
    public long maxScore(int[] nums1, int[] nums2, int k) {
        int n1 = nums1.length, n2 = nums2.length;
        long[][] prev = new long[k + 1][n2 + 1];
        for (int p = 1; p <= k; p++) Arrays.fill(prev[p], (long)-1e18);
        for (int i = 1; i <= n1; i++) {
            long[][] cur = new long[k + 1][n2 + 1];
            for (int p = 0; p <= k; p++) cur[p] = prev[p].clone();
            long v1 = nums1[i - 1];
            for (int p = 1; p <= Math.min(k, i); p++) {
                for (int j = p; j <= n2; j++) {
                    long v2 = nums2[j - 1];
                    if (prev[p - 1][j - 1] > -1e17) {
                        cur[p][j] = Math.max(cur[p][j], prev[p - 1][j - 1] + v1 * v2);
                    }
                    cur[p][j] = Math.max(cur[p][j], cur[p][j - 1]);
                }
            }
            prev = cur;
        }
        return prev[k][n2];
    }
}

